    pos_vars = {f: Int(f'pos_{f}') for f in friends}

    solver = Optimize()

    # Constraints for each friend
    for f in friends:
        # If met, enforce time window and duration
        solver.add(Implies(meet_vars[f], And(
            start_vars[f] >= window_start[f],
            end_vars[f] <= window_end[f],
            end_vars[f] - start_vars[f] >= min_dur[f],
            start_vars[f] >= 0  # cannot start before 9:00 AM
        )))
        # If not met, set dummy values
        solver.add(Implies(Not(meet_vars[f]), And(
            start_vars[f] == 0,
            end_vars[f] == 0,
            pos_vars[f] == 0
        )))
        # Position constraints for met friends
        solver.add(Implies(meet_vars[f], And(pos_vars[f] >= 1, pos_vars[f] <= 3)))

    # Distinct positions for met friends
    for i in range(len(friends)):
        for j in range(i+1, len(friends)):
            f1, f2 = friends[i], friends[j]
            solver.add(Implies(And(meet_vars[f1], meet_vars[f2]), pos_vars[f1] != pos_vars[f2]))

    # Count of met friends
    count_meet = sum([If(meet_vars[f], 1, 0) for f in friends])

    # Ensure positions are consecutive starting from 1
    for i in [1, 2, 3]:
        # At least one friend with position i if i <= count_meet
        cond = Or([And(meet_vars[f], pos_vars[f] == i) for f in friends])
        solver.add(Implies(i <= count_meet, cond))
        # No friend with position i if i > count_meet
        solver.add(Implies(i > count_meet, Not(cond)))

    # Travel constraints: first friend must account travel from start
    for f in friends:
        solver.add(Implies(And(meet_vars[f], pos_vars[f] == 1), start_vars[f] >= travel_start[f]))

    # Travel constraints between consecutive friends
    for f in friends:
        for g in friends:
            if f != g:
                solver.add(Implies(
                    And(meet_vars[f], meet_vars[g], pos_vars[g] == pos_vars[f] + 1),
                    start_vars[g] >= end_vars[f] + travel[(f, g)]
                ))

    # Maximize number of friends met
    solver.maximize(count_meet)

    # Solve
    if solver.check() == sat:
        model = solver.model()
        schedule = []
        schedule.append("You start at Financial District at 9:00AM.")

        # Determine which friends are met and their order
        met_friends = []
        for f in friends:
            if is_true(model[meet_vars[f]]):
                met_friends.append(f)
        # Sort by position
        met_friends.sort(key=lambda f: model[pos_vars[f]].as_long())

        current_location = "Financial District"
        current_time = 0  # minutes from 9:00 AM

        for f in met_friends:
            start = model[start_vars[f]].as_long()
            end = model[end_vars[f]].as_long()
            loc = locations[f]
            travel_time = 0
            if current_location == "Financial District":
                travel_time = travel_start[f]
            else:
                # Find previous friend
                prev_f = met_friends[met_friends.index(f) - 1]
                travel_time = travel[(prev_f, f)]
            arrival_time = current_time + travel_time
            # If arrival is before start, wait
            if arrival_time < start:
                schedule.append(f"You travel to {loc} in {travel_time} minutes and arrive at {minutes_to_time(arrival_time)}.")
                schedule.append(f"You wait until {minutes_to_time(start)}.")
            else:
                # If arrival is exactly at start or later (should not be later due to constraints)
                schedule.append(f"You travel to {loc} in {travel_time} minutes and arrive at {minutes_to_time(arrival_time)}.")
            # Meeting
            schedule.append(f"You meet {names[f]} for {end-start} minutes from {minutes_to_time(start)} to {minutes_to_time(end)}.")
            current_location = loc
            current_time = end

        # If no friends met
        if not met_friends:
            schedule.append("You do not meet any friends.")

        print(schedule)
    else:
        print("No feasible schedule found.")

